import json, urllib.request; results={};
for pace in ('slow','fast'):
 p={'answer_text':'This short pace probe checks the renderer receipt.','label':'agentic-pace-receipt-'+pace,'tone':'neutral_warm','pace':pace,'use_blessed_qra_cache':False,'asr_verify':False};
 req=urllib.request.Request('http://localhost:8018/synthesize-batch', data=json.dumps(p).encode(), headers={'Content-Type':'application/json'});
 r=json.load(urllib.request.urlopen(req, timeout=900));
 pe=r.get('pace_effect') or {};
 assert r.get('ok') is True, r.get('failed_gates');
 assert pe.get('applied') is True, pe;
 assert pe.get('tempo_source')=='requested_pace', pe;
 results[pace]=pe;
assert results['slow']['tempo_factor'] < 1.0 and results['slow']['output_duration_seconds'] > results['slow']['input_duration_seconds'], results;
assert results['fast']['tempo_factor'] > 1.0 and results['fast']['output_duration_seconds'] < results['fast']['input_duration_seconds'], results;
print(json.dumps({'case':'pace_receipt','results':results,'pass':True}, indent=1));
print('RESULT: PASS (pace)')
